    const nextTools = nextResponse.tools ?? [];
    for (const tool of nextTools) {
      const name = tool?.tool?.definition?.name;
      if (name) {
        toolNames.push(name);
      }
    }

    nextPageToken = nextResponse.nextPageToken;
  }

  return toolNames;
}

